/**
 * Builds the official fictional starter universe. Fully deterministic: the
 * same version always produces the same universe, including eight weeks of
 * simulated history generated by the real simulation engine.
 */
import type {
  Championship,
  Promotion,
  Segment,
  SegmentParticipant,
  Show,
  UniverseState,
  Venue,
  Wrestler,
} from "@/lib/domain/entities";
import { addDays } from "@/lib/domain/dates";
import { DEFAULT_SETTINGS, type UniverseSettings } from "@/lib/domain/settings";
import { applyChanges } from "@/lib/simulation/apply";
import { autoBookShow } from "@/lib/simulation/ai-booker";
import { advanceWorld } from "@/lib/simulation/career";
import { buildSimContext } from "@/lib/simulation/context";
import { buildShowChanges } from "@/lib/simulation/effects";
import { createRng, rngUuid } from "@/lib/simulation/rng";
import { simulateShow } from "@/lib/simulation/show";
import {
  STARTER_CHAMPIONSHIPS,
  STARTER_DEALS,
  STARTER_PROMOTIONS,
  STARTER_RIVALRIES,
  STARTER_STORYLINES,
  STARTER_TEAMS,
  STARTER_VENUES,
  STARTER_WRESTLERS,
} from "./starter-data";

export const STARTER_VERSION = "starter-v1";
export const STARTER_HISTORY_START = "2025-11-07";
export const STARTER_GAME_DATE = "2026-01-02";
const TS = "2026-01-01T00:00:00.000Z";

export function emptyUniverseState(universe: UniverseState["universe"]): UniverseState {
  return {
    universe,
    promotions: [],
    venues: [],
    wrestlers: [],
    rosterMemberships: [],
    contracts: [],
    injuries: [],
    teams: [],
    teamMemberships: [],
    chemistry: [],
    championships: [],
    titleReigns: [],
    titleReignHolders: [],
    shows: [],
    tournaments: [],
    segments: [],
    segmentParticipants: [],
    segmentResults: [],
    storylines: [],
    storylineParticipants: [],
    storylineDevelopments: [],
    rivalries: [],
    businessDeals: [],
    financialTransactions: [],
    timelineEvents: [],
  };
}

export interface StarterOptions {
  settings?: Partial<UniverseSettings>;
  name?: string;
}

export function buildStarterUniverse(options: StarterOptions = {}): UniverseState {
  const rng = createRng(STARTER_VERSION);
  const id = () => rngUuid(rng);
  const universeId = id();
  const settings: UniverseSettings = {
    ...DEFAULT_SETTINGS,
    rivalPromotionsEnabled: true,
    financesEnabled: true,
    ...options.settings,
  };

  let state = emptyUniverseState({
    id: universeId,
    owner_id: "00000000-0000-4000-8000-000000000000",
    name: options.name ?? "Ironside & the Rift",
    description: "The official starter universe: two original promotions, thirty-one wrestlers and a World title feud heading to Breaking Point.",
    origin: "starter",
    source_creation_id: null,
    source_version: null,
    attribution: [],
    start_date: STARTER_HISTORY_START,
    game_date: STARTER_HISTORY_START,
    settings,
    schema_version: 1,
    revision: 0,
    idempotency_key: null,
    archived_at: null,
    last_played_at: TS,
    created_at: TS,
    updated_at: TS,
  });
  const u = { universe_id: universeId, created_at: TS, updated_at: TS };

  // Promotions.
  const promoIds: Record<"ipw" | "prw", string> = { ipw: id(), prw: id() };
  for (const key of ["ipw", "prw"] as const) {
    const p = STARTER_PROMOTIONS[key];
    const promotion: Promotion = {
      id: promoIds[key],
      ...u,
      ...p,
      logo_asset_id: null,
      cash_balance: settings.financesEnabled ? settings.startingCapital : 0,
      archived_at: null,
    };
    state.promotions.push(promotion);
    if (settings.financesEnabled) {
      state.financialTransactions.push({
        id: id(),
        universe_id: universeId,
        promotion_id: promotion.id,
        occurred_on: STARTER_HISTORY_START,
        category: "starting_capital",
        amount: settings.startingCapital,
        show_id: null,
        description: "Starting capital",
        created_at: TS,
      });
    }
  }

  // Venues.
  const venueIds: Record<string, string> = {};
  for (const v of STARTER_VENUES) {
    venueIds[v.key] = id();
    const venue: Venue = { id: venueIds[v.key], ...u, name: v.name, city: v.city, region: v.region, capacity: v.capacity, rental_cost: v.rental_cost, prestige: v.prestige, image_asset_id: null, archived_at: null };
    state.venues.push(venue);
  }

  // Wrestlers, rosters, contracts.
  const wIds: Record<string, string> = {};
  for (const s of STARTER_WRESTLERS) {
    wIds[s.key] = id();
    const [in_ring, technical, power, speed, stamina, charisma, mic_skills, selling, psychology, reliability, big_match] = s.attrs;
    const wrestler: Wrestler = {
      id: wIds[s.key],
      ...u,
      ring_name: s.ring_name,
      alternate_name: "",
      real_name: s.real_name,
      gender: s.gender,
      division: s.division,
      billed_from: s.billed_from,
      height_cm: s.height_cm,
      weight_kg: s.weight_kg,
      birth_date: s.birth_date,
      debut_date: s.debut_date,
      biography: s.biography,
      finisher: s.finisher,
      portrait_asset_id: null,
      career_status: "active",
      alignment: s.alignment,
      role: s.role,
      card_position: s.card_position,
      in_ring, technical, power, speed, stamina, charisma, mic_skills, selling, psychology, reliability, big_match,
      popularity: s.popularity,
      momentum: s.card_position === "main_event" ? 20 : s.card_position === "prospect" ? 5 : 0,
      morale: 72,
      fatigue: 0,
      reputation: 60 + Math.round((reliability - 70) / 2),
      archived_at: null,
    };
    state.wrestlers.push(wrestler);
    const joined = s.debut_date > "2020-01-01" ? s.debut_date : "2020-01-01";
    state.rosterMemberships.push({ id: id(), ...u, wrestler_id: wrestler.id, promotion_id: promoIds[s.promotion], started_on: joined, ended_on: null, end_reason: null });
    state.contracts.push({
      id: id(),
      ...u,
      wrestler_id: wrestler.id,
      promotion_id: promoIds[s.promotion],
      starts_on: "2025-01-01",
      // Stagger expiries so contract renewals come up during play.
      ends_on: addDays("2026-03-01", rng.int(0, 300)),
      weekly_salary: s.salary * 2,
      appearance_fee: s.card_position === "main_event" ? 500 : 100,
      exclusive: true,
      status: "active",
    });
  }

  // Teams and factions.
  const teamIds: Record<string, string> = {};
  for (const t of STARTER_TEAMS) {
    teamIds[t.key] = id();
    state.teams.push({ id: teamIds[t.key], ...u, promotion_id: promoIds[t.promotion], kind: t.kind, name: t.name, description: t.description, logo_asset_id: null, formed_on: t.formed_on, disbanded_on: null, experience: t.experience, archived_at: null });
    for (const m of t.members) {
      state.teamMemberships.push({ id: id(), ...u, team_id: teamIds[t.key], wrestler_id: wIds[m], role: "leader" in t && t.leader === m ? "leader" : "member", joined_on: t.formed_on, left_on: null });
    }
    if ("manager" in t && t.manager) {
      state.teamMemberships.push({ id: id(), ...u, team_id: teamIds[t.key], wrestler_id: wIds[t.manager], role: "manager", joined_on: t.formed_on, left_on: null });
    }
    // Partners start with good chemistry.
    for (let i = 0; i < t.members.length; i++)
      for (let j = i + 1; j < t.members.length; j++) {
        const [a, b] = [wIds[t.members[i]], wIds[t.members[j]]].sort();
        if (!state.chemistry.some((c) => c.wrestler_a === a && c.wrestler_b === b)) {
          state.chemistry.push({ universe_id: universeId, wrestler_a: a, wrestler_b: b, partner_score: t.kind === "faction" ? 10 : 30, opponent_score: 0, matches_together: t.kind === "faction" ? 4 : 30, matches_against: 0, updated_at: TS });
        }
      }
  }

  // Championships and history.
  const titleIds: Record<string, string> = {};
  STARTER_CHAMPIONSHIPS.forEach((c, index) => {
    titleIds[c.key] = id();
    const championship: Championship = {
      id: titleIds[c.key],
      ...u,
      promotion_id: promoIds[c.promotion],
      name: c.name,
      description: c.description,
      image_asset_id: null,
      division: c.division,
      format: c.format,
      tier: c.tier,
      prestige: c.prestige,
      status: "active",
      established_on: c.established_on,
      retired_on: null,
      eligibility: c.division === "open" ? {} : { divisions: [c.division] },
      sort_order: index,
    };
    state.championships.push(championship);
    for (const h of c.history) {
      const reignId = id();
      state.titleReigns.push({
        id: reignId,
        ...u,
        championship_id: championship.id,
        team_id: "team" in h && h.team ? teamIds[h.team] : null,
        started_on: h.started_on,
        ended_on: h.ended_on,
        end_reason: h.ended_on ? "lost" : null,
        won_segment_id: null,
        lost_segment_id: null,
        defenses: h.defenses,
        notes: "Pre-game history",
        is_manual: true,
      });
      for (const holder of h.holders) state.titleReignHolders.push({ universe_id: universeId, reign_id: reignId, wrestler_id: wIds[holder] });
    }
  });

  // Storylines.
  const storylineIds: Record<string, string> = {};
  for (const s of STARTER_STORYLINES) {
    storylineIds[s.key] = id();
    state.storylines.push({
      id: storylineIds[s.key],
      ...u,
      promotion_id: promoIds[s.promotion],
      title: s.title,
      kind: s.kind,
      status: s.status,
      intensity: s.intensity,
      objective: s.objective,
      resolution: "",
      description: s.description,
      auto_progress: true,
      started_on: "2025-10-03",
      resolved_on: null,
      championship_id: s.championship ? titleIds[s.championship] : null,
    });
    for (const p of s.participants) {
      state.storylineParticipants.push({ id: id(), ...u, storyline_id: storylineIds[s.key], wrestler_id: wIds[p.key], team_id: null, side: p.side, role: p.role });
    }
    state.storylineDevelopments.push({ id: id(), ...u, storyline_id: storylineIds[s.key], occurred_on: "2025-10-03", show_id: null, segment_id: null, kind: "started", summary: s.description, intensity_delta: 0 });
  }
  for (const r of STARTER_RIVALRIES) {
    const [a, b] = [wIds[r.a], wIds[r.b]].sort();
    const storyline = STARTER_STORYLINES.find((s) => s.participants.some((p) => p.key === r.a) && s.participants.some((p) => p.key === r.b));
    state.rivalries.push({ id: id(), ...u, wrestler_a: a, wrestler_b: b, intensity: r.intensity, matches: 2, started_on: "2025-09-01", last_interaction_on: "2025-10-31", ended_on: null, storyline_id: storyline ? storylineIds[storyline.key] : null });
  }
  for (const d of STARTER_DEALS) {
    state.businessDeals.push({ id: id(), ...u, promotion_id: promoIds[d.promotion], kind: d.kind, partner_name: d.partner_name, amount_per_show: d.amount_per_show, applies_to: [...d.applies_to], starts_on: "2025-01-01", ends_on: "2026-12-31", status: "active" });
  }

  // --- Simulated history -----------------------------------------------------
  const schedule: Array<{ promo: "ipw" | "prw"; date: string; name: string; venue: string; type: Show["show_type"] }> = [];
  for (let week = 0; week < 8; week++) {
    schedule.push({ promo: "ipw", date: addDays(STARTER_HISTORY_START, week * 7), name: `Ironside Uprising #${312 + week}`, venue: "foundry", type: "weekly_tv" });
    schedule.push({ promo: "prw", date: addDays(STARTER_HISTORY_START, week * 7 + 1), name: `Rift Live #${148 + week}`, venue: "harbor", type: "weekly_tv" });
    if (week % 3 === 1) schedule.push({ promo: "ipw", date: addDays(STARTER_HISTORY_START, week * 7 + 2), name: "Ironside Road Tour", venue: "union", type: "house_show" });
  }
  schedule.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));

  for (const [i, entry] of schedule.entries()) {
    const booked = autoBookShow(state, {
      promotionId: promoIds[entry.promo],
      date: entry.date,
      showType: entry.type,
      name: entry.name,
      seed: `${STARTER_VERSION}:book:${i}`,
      venueId: venueIds[entry.venue],
    });
    // Keep the narrative champions in place during pre-game history.
    for (const seg of booked.segments) {
      if (!seg.championship_id) continue;
      const reign = state.titleReigns.find((r) => r.championship_id === seg.championship_id && r.ended_on === null);
      const holders = new Set(state.titleReignHolders.filter((h) => h.reign_id === reign?.id).map((h) => h.wrestler_id));
      const champSide = booked.participants.find((p) => p.segment_id === seg.id && holders.has(p.wrestler_id))?.side;
      if (champSide !== undefined) seg.predetermined_winner_side = champSide;
    }
    state.shows.push(booked.show);
    state.segments.push(...booked.segments);
    state.segmentParticipants.push(...booked.participants);

    const tick = advanceWorld(state, entry.date, `${STARTER_VERSION}:tick:${i}`);
    state = applyChanges(state, tick, TS);
    const ctx = buildSimContext(state, booked.show.id);
    const sim = simulateShow(ctx, `${STARTER_VERSION}:sim:${i}`);
    state = applyChanges(state, buildShowChanges(ctx, sim), TS);
  }
  state = applyChanges(state, advanceWorld(state, STARTER_GAME_DATE, `${STARTER_VERSION}:tick:final`), TS);

  // --- Upcoming schedule -----------------------------------------------------
  const nextUprising = autoBookShow(state, {
    promotionId: promoIds.ipw,
    date: addDays(STARTER_GAME_DATE, 7),
    showType: "weekly_tv",
    name: "Ironside Uprising #320",
    seed: `${STARTER_VERSION}:book:next`,
    venueId: venueIds.foundry,
  });
  state.shows.push(nextUprising.show);
  state.segments.push(...nextUprising.segments);
  state.segmentParticipants.push(...nextUprising.participants);

  for (const [n, offset] of [[321, 14], [322, 21]] as const) {
    state.shows.push(draftShow(id(), universeId, promoIds.ipw, venueIds.foundry, `Ironside Uprising #${n}`, addDays(STARTER_GAME_DATE, offset), "weekly_tv"));
  }
  const breakingPoint = draftShow(id(), universeId, promoIds.ipw, venueIds.meridian, "Ironside: Breaking Point", addDays(STARTER_GAME_DATE, 28), "major_event");
  breakingPoint.target_duration_min = 180;
  breakingPoint.ticket_price = 65;
  breakingPoint.notes = "Annual supershow. Crowe has demanded his rematch.";
  state.shows.push(breakingPoint);
  const mainEvent = makeSegment(id(), universeId, breakingPoint.id, 0, {
    kind: "match",
    match_type: "singles",
    stipulation: "no_dq",
    championship_id: titleIds.ipw_world,
    storyline_id: storylineIds.crown,
    duration_min: 25,
    title: "Crown of Thorns",
    stakes: "If Crowe loses, the Obsidian Order disbands.",
  });
  state.segments.push(mainEvent);
  state.segmentParticipants.push(
    makeParticipant(id(), universeId, mainEvent.id, wIds.vane, 0),
    makeParticipant(id(), universeId, mainEvent.id, wIds.crowe, 1),
  );
  for (let week = 1; week <= 4; week++) {
    state.shows.push(draftShow(id(), universeId, promoIds.prw, venueIds.harbor, `Rift Live #${155 + week}`, addDays(STARTER_GAME_DATE, week * 7 + 1), "weekly_tv"));
  }

  state.universe.game_date = STARTER_GAME_DATE;
  state.universe.revision = 0;
  return state;
}

function draftShow(id: string, universeId: string, promotionId: string, venueId: string, name: string, date: string, type: Show["show_type"]): Show {
  return {
    id,
    universe_id: universeId,
    promotion_id: promotionId,
    venue_id: venueId,
    name,
    show_type: type,
    custom_type_label: "",
    show_date: date,
    status: "draft",
    target_duration_min: type === "major_event" ? 180 : 120,
    ticket_price: type === "major_event" ? 60 : 30,
    poster_asset_id: null,
    notes: "",
    rating: null,
    rating_breakdown: null,
    attendance: null,
    sim_seed: null,
    simulated_at: null,
    version: 0,
    created_at: TS,
    updated_at: TS,
  };
}

function makeSegment(id: string, universeId: string, showId: string, position: number, fields: Partial<Segment> & Pick<Segment, "kind">): Segment {
  return {
    id,
    universe_id: universeId,
    show_id: showId,
    position,
    title: "",
    custom_kind_label: "",
    description: "",
    duration_min: 10,
    storyline_id: null,
    match_type: null,
    stipulation: fields.kind === "match" ? "standard" : null,
    championship_id: null,
    tournament_id: null,
    tournament_round: null,
    stakes: "",
    finish_plan: fields.kind === "match" ? "auto" : null,
    predetermined_winner_side: null,
    interference: [],
    title_changes_on_dq: false,
    created_at: TS,
    updated_at: TS,
    ...fields,
  };
}

function makeParticipant(id: string, universeId: string, segmentId: string, wrestlerId: string, side: number): SegmentParticipant {
  return { id, universe_id: universeId, segment_id: segmentId, wrestler_id: wrestlerId, side, team_id: null, role: "competitor", outcome: null, created_at: TS, updated_at: TS };
}
